/// One id's provenance, or `None` where the id is not one this build ships.
///
/// `None` rather than a default, for the reason `VerificationStatus::parse` gives:
/// a block invented for an unknown id would be a provenance for a number whose code
/// cannot be identified, which is the thing this table exists to prevent.
#[must_use]
pub fn provenance(calc_id: &str) -> Option<&'static ProvenanceStatic> {
    ALL_PROVENANCE.iter().find(|entry| entry.calc_id == calc_id)
}
